using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
public static class GridShiftV20Setup {
 public static void Batch(){try{Configure();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Configure(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");Physics.SyncTransforms();Directory.CreateDirectory("Docs/Validacao20");var cfg=AssetDatabase.LoadAssetAtPath<GridShiftActiveConfig>("Assets/Resources/GridShiftActiveConfig.asset");var factory=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.Contains("Building_Factory")).OrderBy(r=>(r.bounds.center-cfg.depotPosition).sqrMagnitude).First();var bounds=factory.bounds;var outward=-(cfg.depotRotation*Vector3.forward);var rear=bounds.center-Vector3.Scale(outward,bounds.extents);var side=Vector3.Cross(Vector3.up,outward);var shape=cfg.vanPrefab.GetComponent<BoxCollider>();bool found=false;
  for(float distance=4;distance<15&&!found;distance+=1)for(int i=0;i<17&&!found;i++){var at=rear-outward*distance+side*((i%2==0?1:-1)*((i+1)/2)*1.5f);if(!Physics.Raycast(at+Vector3.up*4,Vector3.down,out var floor,20,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||floor.normal.y<.9f)continue;at.y=floor.point.y+.08f;var rotation=Quaternion.LookRotation(side);var extents=shape.size*.78f*.5f;var center=at+rotation*(shape.center*.78f);if(Physics.CheckBox(center,extents*.97f,rotation,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore))continue;bool supported=true;foreach(float x in new[]{-1f,1f})foreach(float z in new[]{-1f,1f}){var corner=center+rotation*new Vector3(extents.x*x,0,extents.z*z);if(!Physics.Raycast(corner+Vector3.up,Vector3.down,out var g,4,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||Mathf.Abs(g.point.y-floor.point.y)>.12f)supported=false;}if(!supported)continue;var road=Object.FindObjectsByType<TrafficRoute>(FindObjectsSortMode.None).Any(r=>r.Valida&&r.pontos.Any(p=>Vector3.ProjectOnPlane(p.position-at,Vector3.up).magnitude<4));if(road)continue;if(Physics.BoxCastAll(center,extents*.9f,side,rotation,6,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore).Any(h=>Mathf.Abs(h.normal.y)<.7f))continue;cfg.vanPosition=at;cfg.vanRotation=rotation;found=true;}
  if(!found)throw new Exception("Nenhuma vaga traseira com suporte e saída livre encontrada.");EditorUtility.SetDirty(cfg);
  var crowd=Object.FindFirstObjectByType<PedestrianManager>();var catalog=AssetDatabase.LoadAssetAtPath<GridShiftCitizenCatalog>("Assets/Resources/GridShiftCitizenCatalog.asset");if(catalog==null){catalog=ScriptableObject.CreateInstance<GridShiftCitizenCatalog>();AssetDatabase.CreateAsset(catalog,"Assets/Resources/GridShiftCitizenCatalog.asset");}catalog.models=crowd.models;catalog.controller=crowd.controller;EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();File.WriteAllText("Docs/Validacao20/localizacao.txt","Factory="+factory.name+"\nBounds="+bounds+"\nRearParking="+cfg.vanPosition+"\nRotation="+cfg.vanRotation.eulerAngles+"\nValidated: four floor corners, body free, six meter exit, away from traffic route points.\nNo city scene overwritten.\n");}
}
